window.PF_DATA_traits = {"meta":{"category":"traits","count":116,"generatedAt":"2026-11-18T15:57:22Z","source":"https://pathfinder.family"},"traits":[{"benefit":"Раз в день вы получаете бонус (штрих) +2 на одну атаку против злого существа. Если существо оказалось не злым, то эта способность потрачена впустую.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"A Sure Thing","nameRu":"Наверняка","parentTypeName":"Штрих фракции","slug":"aSureThing","typeAlias":"silverCrusade","typeName":"Серебряный поход"},{"benefit":"Вас усыновили и вырастили представители народа, отличного от вашего, и вы выросли в чуждой вашему народу среде. В результате вы переняли особенности ваших приемных родителей и их общества. Вы можете немедленно выбрать народный штрих ваших приемных родителей.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Adopted","nameRu":"Приемный","parentTypeName":"Базовый","slug":"adopted","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"У вас добродушный характер, и вы стремитесь дружить и помогать людям, куда бы ни пошли. В своих путешествиях вы останавливаетесь, чтобы помочь другим, рассказываете интересные истории и часто покупаете напитки для посетителей в местных тавернах. Вы приносите хорошее настроение тем, с кем сталкиваетесь, и по этой причине вы часто посещаете важные мероприятия или плодотворные встречи и даже становитесь почётным членом многих семей. Люди находят вас заслуживающим доверия и готовы делиться с вами информацией. Вы получаете бонус штриха +2 к проверкам <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a> для сбора сведений и можете делать это за половину обычного времени. Кроме того, <a href=\"/skill/diplomacy\" class=\"link\">Дипломатия</a> и <a href=\"/skill/knowledge\" class=\"link\">Знание</a> (краеведение) всегда являются для вас классовыми навыками.","book":"Champions of Purity","kind":"trait","nameEn":"Affable","nameRu":"Приветливый","parentTypeName":"Базовый","slug":"affable","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы принадлежите к одной из богатейших семей Магнимара... вернее, раньше принадлежали. Из-за ссоры вы лишились и наследства, и родни. Теперь вы надеетесь уехать куда-нибудь подальше и там прославиться, чтобы посрамить бывших родственников, - ради этого вы и пришли в Общество Искателей. Несмотря на изгнание, вы всё ещё имеете солидный вес в магнимарском обществе и потому получаете бонус +1 (штрих) к проверкам <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a> и <a href=\"/skill/intimidate\" class=\"link\">Запугивания</a> в пределах города. Кроме того, на начало игры у вас имеются: <a href=\"/goodsAndServices?menu=alphabet_Д&scroll=nobleOutfit\" class=\"link\">дворянская одежда</a>, <a href=\"/goodsAndServices?menu=alphabet_П&scroll=signetRing\" class=\"link\">перстень-печатка</a> и один дополнительный неволшебный предмет стоимостью не более 200 зм. Ваша фамилия, вероятно, Дерекси, Каддрен, Миндуриан, Нироден, Скарнетти, Вальдемар, Вандерале или Версаде.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Alabaster Outcast","nameRu":"Изгой из Алебастрового квартала","parentTypeName":"Штрих кампании","slug":"alabasterOutcast","typeAlias":"shatteredStar","typeDescription":"Следующие штрихи кампании помогут создать персонажа, подходящего для серии приключений «Расколотая звезда». Лучше всего, если он живёт в городе Магнимар или недавно сюда прибыл. Также желательно либо состоять в Обществе Искателей, либо быть готовым вступить в его местную ложу.","typeName":"Расколотая звезда"},{"benefit":"Вы учились знанию анатомии будучи студентом в университете или будучи помощником гробовщика или некроманта. Вы знаете, куда наносить свои удары чтобы попасть в жизненно важные органы и получаете +1 бонус (штрих) ко всем броскам проверки подтверждения критических ударов.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Anatomist","nameRu":"Анатом","parentTypeName":"Базовый","slug":"anatomist","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вы хорошо знакомы с историей павших империй. Выберите <a href=\"/skill/knowledge\" class=\"link\">Знание</a> (история) или <a href=\"/skill/linguistics\" class=\"link\">Языкознание</a>. Это умение становится для вас классовым, и вы начинаете читать и говорить на одном из языков: древний осирианский, ацланти, язык циклопов, джистканский, текританский, тассилонский.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Ancient Historian","nameRu":"Древний историк","parentTypeName":"Штрих фракции","slug":"ancientHistorian","typeAlias":"scarabSages","typeName":"Мудрецы скарабея"},{"benefit":"Вы годами обращались с волшебными предметами и умеете проверять их свойства, избегая катастрофических последствий. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/useMagicDevice\" class=\"link\">Использования магических устройств</a> и это навык становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Arcane Archivist","nameRu":"Арканный архивариус","parentTypeName":"Штрих фракции","slug":"arcaneArchivist","typeAlias":"darkArchive","typeName":"Темный архив"},{"benefit":"Вы носили доспехи сколько себя помните, это было частью вашей тренировки оруженосцем рыцаря или просто стремлением казаться героем. Ваши детские доспехи не были настоящей броней, но они нагружали вас не хуже настоящих и вы выросли, двигаясь в таких доспехах с относительной грацией. Когда вы носите любые доспехи, уменьшайте штраф проверки в броне на 1, до минимального значения 0.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Armor Expert","nameRu":"Сроднившийся с доспехом","parentTypeName":"Базовый","slug":"armorExpert","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вас воспитали не бояться нежити - это всего лишь неживые останки ваших уважаемых предков. Раз в день вы можете окружить себя аурой нежити. Неразумная нежить будет игнорировать вас до тех пор, пока вы не предпримете действий против нее (как при <a href=\"/spell/hideFromUndead\" class=\"link\">невидимости для нежити</a>). Защита длится 1 раунд за каждые 2 уровня персонажа (минимум 1 раунд). Если вы предпримете любое агрессивное действие против любой нежити, эффект незамедлительно закончится. Это сверхъестественная способность.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Attuned to the Ancestors","nameRu":"Уважающий предков","parentTypeName":"Штрих фракции","slug":"attunedToTheAncestors","typeAlias":"scarabSages","typeName":"Мудрецы скарабея"},{"benefit":"Вы можете вызвать прилив стихийной энергии для атаки противников. Раз в день вы можете направить на противника элементальную атаку. Это работает как одна из способностей сферы <a href=\"/class/cleric\" class=\"link\">жреца</a>: <a href=\"/god/domain/earth\" class=\"link\">Кислотный дротик</a>, <a href=\"/god/domain/fire\" class=\"link\">Огненный дротик</a>, <a href=\"/god/domain/water\" class=\"link\">Льдинка</a>, <a href=\"/god/domain/air\" class=\"link\">Электрическая дуга</a> или Порыв бури<a href=\"/god/domain/weather\" class=\"link\"></a>. Ваш эффективный уровень <a href=\"/class/cleric\" class=\"link\">жреца</a> считается равным уровню персонажа. Вы можете использовать данную способность дополнительный раз в день на 5-ом уровне и каждые последующие пять уровней.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Balanced Offensive","nameRu":"Сбалансированное нападение","parentTypeName":"Штрих фракции","slug":"balancedOffensive","typeAlias":"concordance","typeName":"Гармония"},{"benefit":"Друид из Великой Ложи открыл вам секреты превращения в животных. Всякий раз, когда вы используете свою классовую способность природный облик, чтобы превратиться в небольшое или среднее животное, данный эффект длится 2 часа (вместо 1) за каждый уровень <a href=\"/class/druid\" class=\"link\">друида</a>.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Beast of the Society","nameRu":"Зверь Общества","parentTypeName":"Базовый","slug":"beastOfTheSociety","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Вы общаетесь со связанными со стихиями существами также легко, как и с обычными животными. Вы получаете бонус (штрих) +1 на проверки понимания животных. Когда вы используете понимание животных для влияния на волшебного зверя с воздушным, огненным, земляным или водным подтипом, на вас не накладывается обычный штраф -4 за влияние на волшебного зверя.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Beastspeaker","nameRu":"Говорящий со зверьми","parentTypeName":"Штрих фракции","slug":"beastspeaker","typeAlias":"concordance","typeName":"Гармония"},{"benefit":"Раз в день при лечении (восстановлении урона по ПЗ) заклинанием или классовой способностью перебросьте все кубики с выпавшим значением 1. Вы должны принять новые результаты, даже если они тоже 1.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Beneficent Touch","nameRu":"Благотворное касание","parentTypeName":"Штрих фракции","slug":"beneficentTouch","typeAlias":"silverCrusade","typeName":"Серебряный поход"},{"benefit":"За годы, проведённые в качестве Искателя, вы познали тайные истоки своей ярости. Вы можете использовать способность ярость на 3 раунда в день больше.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Berserker of the Society","nameRu":"Берсерк Общества","parentTypeName":"Базовый","slug":"berserkerOfTheSociety","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вы были рождены со странным родимым пятном, очень похожим на святой символ божества, которому вы впоследствии будете поклоняться. Это родимое пятно может служить вам сакральным фокусом для колдовства заклинаний и физическим олицетворением вашей веры, усиливая вашу преданность божеству, - вы получаете +2 бонус (штрих) к испытаниям против эффектов очарования и принуждения.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Birthmark","nameRu":"Родимое пятно","parentTypeName":"Базовый","slug":"birthmark","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Благодаря Обществу вы получили доступ к схемам, где изображены слабые места сотен видов гуманоидов и чудовищ. Вы получаете бонус +1 (штрих) к броскам урона при атаках исподтишка.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Blade of the Society","nameRu":"Клинок Общества","parentTypeName":"Базовый","slug":"bladeOfTheSociety","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Давным-давно кровь ваших предков смешалась с кровью драконов. Выберите одно из следующего списка: +1 (штрих) к проверкам <a href=\"/skill/perception\" class=\"link\">Внимания</a>, сумеречное зрение или +2 (штрих) к испытаниям против эффектов, вызывающих сон или паралич.","book":"Ultimate Campaign","kind":"trait","nameEn":"Blood of Dragons","nameRu":"Кровь драконов","prerequisites":"любой народ","slug":"bloodOfDragons","typeAlias":"race","typeDescription":"Народные штрихи привязаны к определённым народам или этносам. Чтобы выбрать народный штрих, ваш персонаж должен относиться к народу или этносу этого штриха. Если впоследствии ваша принадлежность к народу или этносу изменится (что возможно благодаря магии полиморфизма или заклинанию реинкарнации), преимущества, данные этим штрихом, сохранятся - только если ваш разум и память изменятся, вы сможете утратить пользу от этого штриха народа. Конечно же, в таком случае вы также потеряете свои навыки, черты и многое другое.","typeName":"Народный"},{"benefit":"Вас часто дразнили в детстве и вы всегда готовы защитить себя кулаками, когда враг подобрался близко. Вы получаете +1 бонус (штрих) к броскам внеочередных атак, сделанных голыми руками. Запомните, что этот штрих не дает вам возможность делать внеочередные атаки голыми руками, вам нужно будет взять уровень <a href=\"/class/monk\" class=\"link\">монаха</a>, черту <a href=\"/feat/improvedUnarmedStrike\" class=\"link\">Мастер кулачного боя</a> или что-то похожее, чтобы иметь возможность пользоваться этим штрихом. Но это не помешает вам выбрать этот штрих. Вы просто не сможете им пользоваться до некоторого момента.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Bullied","nameRu":"Запуганный","parentTypeName":"Базовый","slug":"bullied","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вы выросли в условиях, где кротость не была в почете, и вам частенько приходилось прибегать к угрозам и насилию, чтобы на вас просто обратили внимание. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/intimidate\" class=\"link\">Запугивания</a>, а навык <a href=\"/skill/intimidate\" class=\"link\">Запугивание</a> - всегда классовый для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Bully","nameRu":"Задира","parentTypeName":"Базовый","slug":"bully","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы выросли среди воров и мерзавцев, их необычная манера говорить и особенности речевых оборотов вам отлично понятны. Любой, кто пытается использовать <a href=\"/skill/bluff\" class=\"link\">Блеф</a>, чтобы передать секретное сообщение вам, получает +5 к проверкам <a href=\"/skill/bluff\" class=\"link\">Блефа</a>. Когда вы пытаетесь перехватить секретное сообщение, используя <a href=\"/skill/senseMotive\" class=\"link\">Проницательность</a>, вы получаете +5 бонус (штрих) к проверке.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Canter","nameRu":"Говорящий на жаргоне","parentTypeName":"Базовый","slug":"canter","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы были рождены на борту корабля и научились сражаться вместе с моряками из Серых Корсаров Андорана. Пока вы находитесь на борту любого водного транспорта, вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/acrobatics\" class=\"link\">Акробатики</a> и <a href=\"/skill/climb\" class=\"link\">Лазания</a>, один из этих навыков (на ваш выбор) становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Captain's Blade","nameRu":"Клинок капитана","parentTypeName":"Штрих фракции","slug":"captainBlade","typeAlias":"libertyEdge","typeName":"Клинок свободы"},{"benefit":"Будучи ребенком травника или помощником в храмовом лазарете, вы часто присматривали за больными и ранеными. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/heal\" class=\"link\">Лечения</a>, а <a href=\"/skill/heal\" class=\"link\">Лечение</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Caretaker","nameRu":"Сиделка","parentTypeName":"Базовый","slug":"caretaker","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Вы поняли, что другие находят вас привлекательным. Вы получаете +1 бонус (штрих) к проверке, когда применяете навыки <a href=\"/skill/bluff\" class=\"link\">Блеф</a> и <a href=\"/skill/diplomacy\" class=\"link\">Дипломатия</a> к персонажам, которые могут быть сексуально заинтересованы в вас, и +1 бонус (штрих) к сложности испытания любого вашего языкового заклинания, примененного к таким существам.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Charming","nameRu":"Обаятельный","parentTypeName":"Базовый","slug":"charming","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы выросли на улице большого города, в результате чего развили в себе умение обчищать карманы и прятать небольшие предметы на себе. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/sleightOfHand\" class=\"link\">Ловкости рук</a>, а <a href=\"/skill/sleightOfHand\" class=\"link\">Ловкость рук</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Child of the Streets","nameRu":"Выросший на улице","parentTypeName":"Базовый","slug":"childOfTheStreets","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы долго служили в городском храме и не только освоили обычаи дворянства, но и посвятили много времени библиотеке храма, изучая вашу религию. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (высший свет) и <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (религия), и один из этих навыков (на ваш выбор) - всегда классовый для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Child of the Temple","nameRu":"Воспитанник храма","parentTypeName":"Базовый","slug":"childOfTheTemple","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Ваше ученичество или раннее обучение было сосредоточено на прикладной магии. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/spellcraft\" class=\"link\">Колдовства</a>, а <a href=\"/skill/spellcraft\" class=\"link\">Колдовство</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Classically Schooled","nameRu":"Классическое обучение","parentTypeName":"Базовый","slug":"classicallySchooled","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Ваши союзники из Серебряного похода много рассказали вам о божествах и их поклонниках по всему Голариону. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (религия), и этот навык становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Comparative Religion","nameRu":"Сравнительная религия","parentTypeName":"Штрих фракции","slug":"comparativeReligion","typeAlias":"silverCrusade","typeName":"Серебряный поход"},{"benefit":"Ваше детство было жестоким, но вы упорно не теряли волю и веру в себя, как бы ни было тяжело, вы шли с поднятой головой и все преодолевали. Вы получаете +2 бонус (штрих) к испытаниям против эффектов ужаса.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Courageous","nameRu":"Храбрый","parentTypeName":"Базовый","slug":"courageous","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вас всегда влекла магия, возможно, потому что вы были ребенком мага или священника. Вы часто пробирались в лабораторию, чтобы повозиться с компонентами заклинаний и магическими устройствами, и зачастую это приводило к плачевным последствиям в виде небольших разрушений или головных болей у родителей. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/useMagicDevice\" class=\"link\">Использования магических устройств</a>, а <a href=\"/skill/useMagicDevice\" class=\"link\">Использование магических устройств</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Dangerously Curious","nameRu":"Чрезвычайно любопытный","parentTypeName":"Базовый","slug":"dangerouslyCurious","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Наблюдая за величайшими воинами Общества, вы научились новым защитным приёмам при сражении в доспехах. Вы получаете бонус +1 (штрих) к классу брони, когда носите среднюю или тяжёлую броню.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Defender of the Society","nameRu":"Защитник Общества","parentTypeName":"Базовый","slug":"defenderOfTheSociety","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Взросление в непростом или в опасном окружении отточило ваше восприятие. Вы получаете +1 бонус (штрих) к испытаниям Реакции.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Deft Dodger","nameRu":"Увертливый","parentTypeName":"Базовый","slug":"deftDodger","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вы адепт сотворения заклинаний даже в самых ненадёжных ситуациях. Вы получаете +1 (штрих) на проверки концентрации. Этот бонус увеличивается до +4, когда вы становитесь схваченным, обездвиженным, опутанным или при плохой погоде.","book":"Ultimate Campaign","kind":"trait","nameEn":"Desperate Resolve","nameRu":"Отчаянная решимость","parentTypeName":"Базовый","slug":"desperateResolve","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Вы носите знак высшего демона, и любое злое существо должно подумать дважды, прежде чем перейти вам дорогу. Вы получаете бонус (штрих) +2 на все проверки <a href=\"/skill/bluff\" class=\"link\">Блефа</a>, <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a>, <a href=\"/skill/intimidate\" class=\"link\">Запугивания</a> и <a href=\"/skill/senseMotive\" class=\"link\">Проницательности</a> против всех злых потусторонних существ.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Devil's Mark","nameRu":"Метка дьявола","parentTypeName":"Штрих фракции","slug":"devilMark","typeAlias":"darkArchive","typeName":"Темный архив"},{"benefit":"Вам было тяжело найти для себя образец законопослушного гражданина в детстве или юности. Причины, по которым вы обратились к жизни преступника, могут быть разнообразны, но в конечном итоге вы пришли к известному в определённых кругах преступном главарю с хорошими связями по имени Гаэдрен Ламм. Вам была известна его репутация змеи и коварного негодяя, но по собственным соображения вы решили не отказывать ему, когда он предложил вам возможность работать на него. Возможно, вы предполагали, что станете исключением или что сможете справиться с ним или, возможно, даже планировали предать его. Но когда работа была выполнена, Гаэдрен поднял руку и первым потопил вас. Возможно, вы провели время в тюрьме, возможно, были избиты его бандитами и оставлены умирать, а может просто он украл вашу прибыль. Независимо от причины, Гаэдрен обидел вас, и вы хотите отомстить.\nВыберите одно из следующих преимуществ.\n<b>Жаждущий мести:</b> вы никогда не простите Гаэдрена за предательство, и поклялись заставить его заплатить за содеяное. Неважно, где вы хотите увидеть его гниющее тело: в тюрьме или на мелкой могиле - вы надеетесь вкусить вкус мести когда-нибудь. Всякий раз, когда вы наносите урон оружием ближнего боя по застигнутому врасплох существу, вы получаете бонус (штрих) +1 на броске уроне.\n<b>Исправившийся преступник:</b> вы отказались от преступной жизни и сумели отговориться от любых последствий, таких как тюремное заключение или штрафы. Вы сказали себе, что предпочитаете оставить прошлое, но желание увидеть, как Гаэдрен Ламм заплатит за свои преступления, всё ещё горит в вас. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a> и <a href=\"/skill/diplomacy\" class=\"link\">Дипломатия</a> становится классовым навыков для вас.","book":"Curse of the Crimson Throne","kind":"trait","nameEn":"Devoted","nameRu":"Преданый","parentTypeName":"Штрих кампании","slug":"devoted","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"Ваша вера в природу или в одного из природных божеств позволила вам легко разбираться с темами, связанными с этим. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (география) и <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (природа), и один из этих навыков (на ваш выбор) - всегда классовый для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Devotee of the Green","nameRu":"Преданный природе","parentTypeName":"Базовый","slug":"devoteeOfTheGreen","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Вы бы не пережили детство без помощи родственника друга или товарища, которому можно было бы доверить отвлекать ваших противников так долго, что вы могли наносить немного больше урона. Этот компаньон может быть игровым персонажем или персонажем ведущего (он уже даже может и не быть с вами). Когда вы наносите удар по противнику в тисках, он получает 1 дополнительный пункт урона (этот урон прибавляется к вашему базовому урону и умножается при критическом ударе). Этот дополнительный урон - бонус (штрих).","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Dirty Fighter","nameRu":"Мастер подлых приемов","parentTypeName":"Базовый","slug":"dirtyFighter","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Нет такого преступления, которое было бы слишком низким для Гаэдрена Ламма и его бандитов - банды низкопробных убийц, похитителей и наркоторговцев, которые работают в Средних Землях Корвосы. Вы потеряли кого-то из-за Ламма, и теперь жаждете мести. Пока Ламм остаётся живым и свободным, вы не умрёте, пока ваши отрицательные ПЗ не достигнут значения <a href=\"/ability/constitution\" class=\"link\">Выносливости</a> + 3. После того, как Ламм заключён в тюрьму или убит, вы теряете прежнее преимущество, но получаете 3 постоянных ПЗ.","book":"Varisia, Birthplace of Legends","kind":"trait","nameEn":"Dockside Avenger","nameRu":"Портовый мститель","parentTypeName":"Штрих кампании","slug":"docksideAvenger","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"Как и синие драконы, которых почитает ваше племя, вы обладаете частицей иллюзорной магии. Вы можете использовать <i><a href=\"/spell/ghostSound\" class=\"link\">призрачный звук</a></i> дважды в день в качестве псевдозаклинания. Уровень заклинателя для этого эффекта равен уровню вашего персонажа. СЛ испытания этого псевдозаклинания основана на <a href=\"/ability/intelligence\" class=\"link\">Интеллекте</a>.","book":"Kobolds of Golarion","kind":"trait","nameEn":"Draconic Echo","nameRu":"Драконье эхо","prerequisites":"<a href=\"/race/kobold\" class=\"link\">кобольд</a>","slug":"draconicEcho","typeAlias":"race","typeDescription":"Народные штрихи привязаны к определённым народам или этносам. Чтобы выбрать народный штрих, ваш персонаж должен относиться к народу или этносу этого штриха. Если впоследствии ваша принадлежность к народу или этносу изменится (что возможно благодаря магии полиморфизма или заклинанию реинкарнации), преимущества, данные этим штрихом, сохранятся - только если ваш разум и память изменятся, вы сможете утратить пользу от этого штриха народа. Конечно же, в таком случае вы также потеряете свои навыки, черты и многое другое.","typeName":"Народный"},{"benefit":"Кто-то, кого вы знаете, стал зависим от \"дрожи\", наркотика, выделяемого из яда тропических арахнидов, известных как сонные пауки. Наркотик вызывает сон, наполненный яркими сновидениями, во время которого тело принявшего его часто дрожит и трясётся, что дало веществу его уличное название. Вы всегда думали о дрожи, как о проблеме низшего класса, но затем кто-то, кого вы знаете, получил передозировку этой дрянью. Вы провели небольшое расследование и узнали, что негодяй, подсадивший вашего друга, это главарь банды по имени Гаэдрен Ламм. К несчастью, стража, кажется, занята более крупными дельцами. У них нет времени, чтобы посвятить большое количество сил тому, что они называют \"небольшим игроком в проблемах бедняков\". Кажется, что если деятельность Гаэдрена и будет остановлена, то это будет зависеть от вас.\nВыберите одно из следующих преимуществ.\n<b>Зависимый друг:</b> зависимый - это друг или любимый человек, который мог пережить, а мог и не пережить передозировку. Ваше расследование на месте преступления и среди местной политики дали вам приличное образование в области уличных знаний. Вы получаете бонус +1 к проверкам <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (краеведение) и <a href=\"/skill/knowledge\" class=\"link\">Знание</a> (краеведение) становится классовым навыков для вас.\n<b>Личная зависимость:</b> вы были тем самым зависимым. Вы вините Гаэдрена в вашем столкновении со смертью и ненавидите то, как его наркотики вызывают схожие проблемы среди другой молодежи. К счастью, ваше тело быстро восстанавливается от ядов и у вас есть бонус +1 к испытаниям Стойкости.","book":"Curse of the Crimson Throne","kind":"trait","nameEn":"Drug Addict","nameRu":"Наркозависимый","parentTypeName":"Штрих кампании","slug":"drugAddict","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"С самых ранних пор ваш наставник старался уверить вас в том, что ваши сакральные силы ничем не отличаются от сакральных сил других религий. Эта философия позволила вам легче взаимодействовать с теми, кто не разделяет ваши взгляды. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a>, а <a href=\"/skill/diplomacy\" class=\"link\">Дипломатия</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Ease of Faith","nameRu":"Веротерпимый","parentTypeName":"Базовый","slug":"easeOfFaith","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Хоть вы и росли под крылом одной из многочисленных магнимарских банд Скарни, вы никогда не вписывались в компанию своих осёдлых городских собратьев. Общество Искателей разглядело в вас будущего агента, ведь вы не раз поражали их своей ловкостью и прекрасным знанием улиц. Со временем вы впали в немилость у Скарни и в конце концов ушли, чтобы заняться чем-то поинтереснее бандитизма. Однако вы ещё помните те уроки, что преподали вам знакомые преступники. Вы получаете бонус +2 (штрих) к проверкам <a href=\"/skill/bluff\" class=\"link\">Блефа</a> для передачи тайных сообщений. Кроме того, каждый раз, когда вы совершаете добивающий удар, вы наносите дополнительно <a href=\"/dice?notation=1d6&roll\" class=\"link\">1d6</a> урона.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Ex-Sczarni","nameRu":"Бывший Скарни","parentTypeName":"Штрих кампании","slug":"exSczarni","typeAlias":"shatteredStar","typeDescription":"Следующие штрихи кампании помогут создать персонажа, подходящего для серии приключений «Расколотая звезда». Лучше всего, если он живёт в городе Магнимар или недавно сюда прибыл. Также желательно либо состоять в Обществе Искателей, либо быть готовым вступить в его местную ложу.","typeName":"Расколотая звезда"},{"benefit":"В закромах авессаломской Великой Ложи хранится множество тайн чудесной силы богов, и вы изучили всё, что нашли, о своём божестве. Вы можете использовать божественную силу, проводя энергию, на один раз в день больше.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Exalted of the Society","nameRu":"Одухотворённый Общества","parentTypeName":"Базовый","slug":"exaltedOfTheSociety","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Хотя вы в Магнимаре сравнительно недавно, вы не какой-то наивный путешественник. Вас прислала сюда другая ложа Общества Искателей с заданием увидеть Варисию своими глазами и побольше узнать об этой приграничной стране. Прибыв в город, вы явились в местную ложу и предложили свои услуги капитану-куратору. Чтобы объяснить знание дальних земель, выберите своей родиной какую-нибудь страну, кроме Варисии, и выучите один из языков, на котором говорят в этой стране, в качестве дополнительного. Кроме того, выберите один из следующих навыков: <a href=\"/skill/survival\" class=\"link\">Выживание</a>, <a href=\"/skill/handleAnimal\" class=\"link\">Дрессировка</a>, <a href=\"/skill/knowledge\" class=\"link\">Знание</a> (география) или <a href=\"/skill/linguistics\" class=\"link\">Языкознание</a>. Вы получаете бонус +1 (штрих) к проверкам этого навыка, и он всегда считается классовым для вас.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Exchange Agent","nameRu":"Агент по обмену","parentTypeName":"Штрих кампании","slug":"exchangeAgent","typeAlias":"shatteredStar","typeDescription":"Следующие штрихи кампании помогут создать персонажа, подходящего для серии приключений «Расколотая звезда». Лучше всего, если он живёт в городе Магнимар или недавно сюда прибыл. Также желательно либо состоять в Обществе Искателей, либо быть готовым вступить в его местную ложу.","typeName":"Расколотая звезда"},{"benefit":"В юности вы часами совершенствовали искусство дуэли, сосредотачиваясь на победе над единичным противником. Вы получаете бонус (штрих) +1 к КБ пока находитесь рядом со всего одним противником. Этот бонус (штрих) не учитывается против касательных атак, или когда вы лишены своего бонуса <a href=\"/ability/dexterity\" class=\"link\">Ловкости</a>.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Expert Duelist","nameRu":"Искусный дуэлянт","parentTypeName":"Штрих фракции","slug":"expertDuelist","typeAlias":"sovereignCourt","typeName":"Суверенный двор"},{"benefit":"Вы провели ваше отрочество будучи клинком Оппары и научились с помощью стиля улучшать отношения с окружающими. До тех пор, пока вы носите одежду и украшения на 80 золотых, вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/bluff\" class=\"link\">Блефа</a>, <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a> и <a href=\"/skill/senseMotive\" class=\"link\">Проницательности</a>, и один из этих навыков становится классовым для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Fashionable","nameRu":"Модный","parentTypeName":"Штрих фракции","slug":"fashionable","typeAlias":"sovereignCourt","typeName":"Суверенный двор"},{"benefit":"У вас был дар влипать в неприятности, когда вы были еще ребенком. Из-за этого у вас хорошо подвешен язык еще с детства. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/bluff\" class=\"link\">Блефа</a>, а <a href=\"/skill/bluff\" class=\"link\">Блеф</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Fast-Talker","nameRu":"Балабол","parentTypeName":"Базовый","slug":"fastTalker","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы провели множество часов на тренировках с клинками, посещая уроки изящного фехтования, оплаченные вашими родителями или учась у неизвестного фехтовальщика, преступника в прошлом. Вы получаете +1 бонус (штрих) к внеочередным атакам, сделанным кинжалами, мечами или другим похожим клинковым оружием.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Fencer","nameRu":"Фехтовальщик","parentTypeName":"Базовый","slug":"fencer","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"В детстве вашим главным занятием были уроки некой дисциплины (музыкальной или научной) или ваши условия дома были ужасными, это научило вас сосредотачиваться на текущей задаче и игнорировать отвлекающие факторы. Вы получаете +2 бонус (штрих) к проверкам концентрации.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Focused Mind","nameRu":"Сосредоточенный разум","parentTypeName":"Базовый","slug":"focusedMind","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Ваши добрые заклинания особенно сильны и действуют словно ваш уровень заклинателя на 1 уровень выше. Этот штрих делает вашу ауру более сильной (на 1 шаг).","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Force for Good","nameRu":"Сила добра","parentTypeName":"Штрих фракции","slug":"forceForGood","typeAlias":"silverCrusade","typeName":"Серебряный поход"},{"benefit":"Кто-то, кого Вы знаете и любите, был обвинен в убийстве. Слова предполагаемого свидетеля - местного рыбака - было бы достаточно, чтобы закрыть это дело, но у обвиняемого было хорошее алиби, чтобы вынесение приговора не было немедленным. Кто-то встретился с рыбаком и обнаружил, что его запугал для предоставления лжесвидетельства и вынудил подложить оружие убийства настоящий убийца - местный преступник по имени Гаэдрен Ламм, чьи головорезы убили рыбака, прежде чем он смог отречься от своих показаний. Хотя это устранило ключевого свидетеля и привело к освобождению обвиняемого, клеймо было достаточным, чтобы сильно повредить его репутации. Если вы найдёте Гаэдрена, вы уверены, что сможете найти доказательства, которые свяжут его с убийством и смогут очистить имя обвиняемого.\n<b>Исключённый:</b> вы были тем самым обвиняемым. Хотя вас в итоге и освободили, когда ваш друг встретился с рыбаком и выудил правду, урон уже был нанесён. Вас заставили покинуть школу или церковь. В результате, вам пришлось тренироваться самостоятельно и вы пообещали себе, что станете лучше в выбранной Вами профессии несмотря на отвергнувшее вас окружение. Вы получаете бонус (штрих) +1 к проверкам <a href=\"/skill/spellcraft\" class=\"link\">Колдовства</a> и <a href=\"/skill/spellcraft\" class=\"link\">Колдовство</a> становится классовым навыков для вас.\n<b>Семейная честь:</b> человек, которого подставили, был членом семьи, возможно, отцом или сестрой. Вам удалось обмануть рыбака, чтобы он открыл Вам правду, используя навыки общения. Вы получаете бонус (штрих) +1 к проверкам <a href=\"/skill/bluff\" class=\"link\">Блефа</a> и <a href=\"/skill/bluff\" class=\"link\">Блеф</a> становится классовым навыков для вас.","book":"Curse of the Crimson Throne","kind":"trait","nameEn":"Framed","nameRu":"Подставленный","parentTypeName":"Штрих кампании","slug":"framed","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"Ваша семья очень долго сражалась с тиранией, и вы стали очень сведущи в партизанской войне. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/stealth\" class=\"link\">Скрытности</a> и бонус (штрих) +1 на атаки во время предбоевого раунда.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Freedom Fighter","nameRu":"Борец за свободу","parentTypeName":"Штрих фракции","slug":"freedomFighter","typeAlias":"libertyEdge","typeName":"Клинок свободы"},{"benefit":"Ледяное дыхание белого дракона наполняет ваши лёгкие. Раз в день вы можете быстро выдохнуть, чтобы создать ледяное облако густого тумана, которое быстро оседает на землю. Этот ледяной туман покрывает площадь в 10 квадратных футов скользким льдом, по которому так же трудно передвигаться, как по наледи (Основная книга правил, стр. 464 [можно найти <a href=\"/wilderness\" class=\"link\">здесь</a> в разделе Пустыни]).","book":"Kobolds of Golarion","kind":"trait","nameEn":"Frost Spitter","nameRu":"Морозный плевун","prerequisites":"<a href=\"/race/kobold\" class=\"link\">кобольд</a>","slug":"frostSpitter","typeAlias":"race","typeDescription":"Народные штрихи привязаны к определённым народам или этносам. Чтобы выбрать народный штрих, ваш персонаж должен относиться к народу или этносу этого штриха. Если впоследствии ваша принадлежность к народу или этносу изменится (что возможно благодаря магии полиморфизма или заклинанию реинкарнации), преимущества, данные этим штрихом, сохранятся - только если ваш разум и память изменятся, вы сможете утратить пользу от этого штриха народа. Конечно же, в таком случае вы также потеряете свои навыки, черты и многое другое.","typeName":"Народный"},{"benefit":"Ваша заинтересованность в магии была вызвана тем, что вы были свидетелем заклинания, проведенного невероятным образом и, возможно, это воздействовало на вас физически или духовно. Это воздействие магии позволило вам взаимодействовать с магией с легкостью, недоступной остальным. Выберите одно заклинание, когда берете этот штрих, теперь, когда вы колдуете это заклинание, вы получаете +1 бонус (штрих) к своему уровню заклинателя.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Gifted Adept","nameRu":"Талантливый приверженец","parentTypeName":"Базовый","slug":"giftedAdept","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Вы потомственный вор и форточник. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/disableDevice\" class=\"link\">Механики</a> и <a href=\"/skill/sleightOfHand\" class=\"link\">Ловкости рук</a>, и один из этих навыков (на ваш выбор) становится классовым для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Gold Finger","nameRu":"Золотой палец","parentTypeName":"Штрих фракции","slug":"goldFinger","typeAlias":"theExchange","typeName":"Торговый союз"},{"benefit":"Вы знаете, как с легкостью заставить людей делать то, что вы хотите. При подкупе неигрового персонажа, вы можете заплатить на 10% меньше и достичь такого же результата, что и персонаж без этого штриха.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Greasy Palm","nameRu":"Загребущая рука","parentTypeName":"Штрих фракции","slug":"greasyPalm","typeAlias":"theExchange","typeName":"Торговый союз"},{"benefit":"Месяцы медитации и тренировок под руководством величайших заклинателей усилили ваши магические способности. Вы получаете одну дополнительную ячейку заклинания 0-го круга.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Greater Adept of the Society","nameRu":"Великий адепт Общества","parentTypeName":"Базовый","slug":"greaterAdeptOfTheSociety","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Потратив бессчётные часы на штудирование книг по магии, вы научились наносить врагам больше урона. Всякий раз, когда вы сотворяете заклинание, наносящее урон, вы получаете бонус +1 (штрих) к общему нанесённому урону. Этот урон имеет дескриптор «сила» независимо от типа урона, наносимого заклинанием.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Havoc of the Society","nameRu":"Разящая рука Общества","parentTypeName":"Базовый","slug":"havocOfTheSociety","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Вы некоторое время помогали ремесленнику, который создавал магические предметы, и он научил вас некоторым своим особым приемам, позволяющим упрощать и удешевлять производство магических предметов. Когда вы будете создавать магический предмет, количество золотых монет, необходимых для создания этого предмета, будет меньше на 5%.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Hedge Magician","nameRu":"Экономный маг","parentTypeName":"Базовый","slug":"hedgeMagician","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Вы впитали еретические взгляды с молоком матери и вам не только было сложно принять большинство религиозных верований, но и пришлось свыкнуться с тем фактом, что к вам или к вашим близким часто относились как к изгоям. Из-за этого вы отвернулись от религиозных учений и пока вы не обладаете ни одним уровнем класса с сакральными магическими силами вы получаете +1 бонус (штрих) к испытаниям против сакральных заклинаний.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"History of Heresy","nameRu":"Потомственный еретик","parentTypeName":"Базовый","slug":"historyOfHeresy","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Вы изучили десятки древних текстов по боевым искусствам, которые есть только в библиотеке Общества Искателей, и стали более сведущи в этих искусствах, чем многие другие. Ваш запас энергии ци увеличивается на 1 пункт.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Honored Fist of the Society","nameRu":"Кулак Общества","parentTypeName":"Базовый","slug":"honoredFistOfTheSociety","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Репутация вашего наследия даёт вам определённую степень устрашающего уважения. Вы получаете +1 (штрих) на проверки <a href=\"/skill/intimidate\" class=\"link\">Запугивания</a>. Если ваше наследие связано с определённым типом существ, бонус увеличивается до +2 при взаимодействии с существами этого типа.","book":"Ultimate Campaign","kind":"trait","nameEn":"Imposing Scion","nameRu":"Внушительный потомок","parentTypeName":"Базовый","slug":"imposingScion","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Ваше напыщенное щегольство часто обескураживает окружающих. Раз в день как полнораундовое действие вы можете попытаться отвлечь соседних противников длительной демонстрацией своих боевых навыков. Все соседние противники должны пройти проверку Воли со сложностью 10 + 1/2 вашего уровня + ваш модификатор <a href=\"/ability/charisma\" class=\"link\">Харизмы</a> или получить потрясенное состояние на 1 раунд.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Impressive Presence","nameRu":"Впечатляющее присутствие","parentTypeName":"Штрих фракции","slug":"impressivePresence","typeAlias":"sovereignCourt","typeName":"Суверенный двор"},{"benefit":"Ваш сильный и самоуверенный вид делает вас менее подверженным чужой власти и контролю. Вы получаете бонус (штрих) +1 на испытания против заклинаний и эффектов <a href=\"/spell/schools\" class=\"link\">очарования</a>.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Indomitable","nameRu":"Неукротимый","parentTypeName":"Штрих фракции","slug":"indomitable","typeAlias":"libertyEdge","typeName":"Клинок свободы"},{"benefit":"Вы были рождены в регионе, где ваша вера была не популярна, однако вы не предали ее. Ваша постоянная борьба за поддержание собственной веры укрепила ваши стремления. В результате вы получаете +1 бонус (штрих) к испытаниям Воли.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Indomitable Faith","nameRu":"Истово верующий","parentTypeName":"Базовый","slug":"indomitableFaith","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Когда вы делаете предложение, собеседник думает, что изначально это была его идея. Вы получаете бонус +3 на проверки <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a>, чтобы попросить это существо сделать для вас что-либо.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Influential","nameRu":"Влиятельный","parentTypeName":"Штрих фракции","slug":"influential","typeAlias":"sovereignCourt","typeName":"Суверенный двор"},{"benefit":"Капитан-куратор Валсин предпочитает быть в курсе всего в Сообществе следопытов, и вы тоже переняли эту привычку. Выберите <a href=\"/skill/diplomacy\" class=\"link\">Дипломатию</a> или <a href=\"/skill/knowledge\" class=\"link\">Знание</a> (краеведение); вы получаете бонус (штрих) +1 на проверки выбранного навыка и он становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Insider Knowledge","nameRu":"Хорошо осведомлен","parentTypeName":"Штрих фракции","slug":"insiderKnowledge","typeAlias":"grandLodge","typeName":"Великая ложа"},{"benefit":"Вы совершили свое первое убийство в очень раннем возрасте и обнаружили, что военное дело или убийство вам по нраву. Вы гордились удачно нанесенными ударами или упивались чужой болью, проворачивая клинок в ране. Вы наносите дополнительный урон, равный критическому множителю оружия, которым вы нанесли успешный критический удар. Этот дополнительный урон добавляется к суммарному урону и сам не умножается на критический множитель. Этот дополнительный урон - бонус (штрих).","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Killer","nameRu":"Душегуб","parentTypeName":"Базовый","slug":"killer","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вы — один из ярых верующих среди кобольдов, пользующийся уважением в своём сообществе. Вы получаете +2 (штрих) на проверки <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a> при общении с другими кобольдами. Кроме того, если ваше божество дарует сферу <a href=\"/god/domain/earth\" class=\"link\">Земли</a>, <a href=\"/god/domain/trickery\" class=\"link\">Обмана</a> или <a href=\"/god/domain/artifice\" class=\"link\">Созидания</a>, то ваша вера кобольдов даёт доступ к соответствующей подсфере: Радиации, <a href=\"/god/subdomain/ambush\" class=\"link\">Засады</a> или Ловушек.","book":"Kobolds of Golarion","kind":"trait","nameEn":"Kobold Faith","nameRu":"Вера кобольдов","prerequisites":"<a href=\"/race/kobold\" class=\"link\">кобольд</a>","slug":"koboldFaith","typeAlias":"race","typeDescription":"Народные штрихи привязаны к определённым народам или этносам. Чтобы выбрать народный штрих, ваш персонаж должен относиться к народу или этносу этого штриха. Если впоследствии ваша принадлежность к народу или этносу изменится (что возможно благодаря магии полиморфизма или заклинанию реинкарнации), преимущества, данные этим штрихом, сохранятся - только если ваш разум и память изменятся, вы сможете утратить пользу от этого штриха народа. Конечно же, в таком случае вы также потеряете свои навыки, черты и многое другое.","typeName":"Народный"},{"benefit":"Вы мастер в хранении и обращении с книгами и легко находите в них необходимую информацию. Вы получаете бонус (штрих) +1 к проверкам <a href=\"/skill/linguistics\" class=\"link\">Языкознания</a> и <a href=\"/skill/profession\" class=\"link\">Профессии</a> (библиотекарь), и один из этих навыков (на ваш выбор) становится для вас классовым. Раз в день при получении бонуса за прочтение книги вы можете увеличить этот бонус на 1.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Librarian","nameRu":"Библиотекарь","parentTypeName":"Штрих фракции","slug":"librarian","typeAlias":"darkArchive","typeName":"Темный архив"},{"benefit":"Кто-то, кого вы любили, встретил смерть от ножа в тёмной аллее однажды ночью. Вас вызвала на место преступления Стража Корвосы, чтобы опознать тело, и как бы это ни было тяжело для вас, вы также заметили, что на пальце любимого человека нет кольца. Кто бы ни убил вашего любимого, он украл это кольцо - вы уверены в этом. Вы провели небольшое самостоятельное расследование и недавно нашли кольцо в продаже у местного торговца. Хотя к вашему великому разочарованию, у вас пока нет 500 зм, чтобы выкупить его, торговец сказал, у кого он приобрёл кольцо: у человека по имени Гаэдрен Ламм. Похоже, что это и есть тот преступник, который убил вашего любимого, или, по крайней мере, знает, кто это сделал. Единственная проблема - это найти его.\nВыберите одно из следующих преимуществ.\n<b>В полном одиночестве:</b> жертва убийства была вашим возлюбленным. Со смертью любимого умерла и часть вас, сделав вас угрюмым, мрачным и склонным к тёмным мыслям. Вы получаете бонус (штрих) +1 к проверкам <a href=\"/skill/intimidate\" class=\"link\">Запугивания</a> и <a href=\"/skill/intimidate\" class=\"link\">Запугивание</a> становится классовым навыков для вас.\n<b>Осиротевший:</b> жертва убийцы была вашим единственным живым родителем. Вам пришлось много работать, чтобы свести концы с концами и позаботиться о самом себе и возможных братьях и сёстрах, и часто приходилось копаться в мусор, чтобы найти еду. Вы получаете бонус (штрих) +1 к проверкам <a href=\"/skill/survival\" class=\"link\">Выживания</a> и <a href=\"/skill/survival\" class=\"link\">Выживание</a> становится классовым навыков для вас.","book":"Curse of the Crimson Throne","kind":"trait","nameEn":"Love Lost","nameRu":"Потерянная любовь","parentTypeName":"Штрих кампании","slug":"loveLost","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"Вы сопротивляетесь попыткам отговорить вас от подчинения Децемвирату. Вы получаете бонус (штрих) +1 к испытаниям против заклинаний и эффектов <a href=\"/spell/schools\" class=\"link\">очарования</a>.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Loyalty","nameRu":"Лояльность","parentTypeName":"Штрих фракции","slug":"loyalty","typeAlias":"grandLodge","typeName":"Великая ложа"},{"benefit":"Благодаря огромной сокровищнице музыкальных знаний в хранилище под Великой Ложей Авессалома вам открылись секреты мастерства величайших музыкантов Голариона. Вы можете использовать выступление барда на 3 раунда в день больше.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Maestro of the Society","nameRu":"Маэстро Общества","parentTypeName":"Базовый","slug":"maestroOfTheSociety","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вас воспитывало магическое (полностью или частично) существо, возможно оно нашло вас брошенным в лесу или же ваши родители часто оставляли вас под опекой магического прислужника. Этот постоянный контакт с магией загадочным образом позволил вам легко вникать в магическую суть, даже когда ваш разум занят другими увлечениями и задачами. Выберите класс, когда берете этот штрих, теперь вы получаете +2 бонус (штрих) к уровню заклинателя этого класса, но ваш уровень заклинателя будет не больше вашего текущего количества Костей жизни.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Magical Knack","nameRu":"Привыкший к магии","parentTypeName":"Базовый","slug":"magicalKnack","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Один из ваших родителей был одаренным заклинателем, который не только часто пользовался метамагией, но и разработал множество магических устройств и, возможно, парочку заклинаний и вы унаследовали частичку этого величия. Выберите одно заклинание когда берете этот штрих. Когда вы будете применять метамагию к этому заклинанию, считайте повышение круга заклинания меньше на 1.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Magical Lineage","nameRu":"Магическое происхождение","parentTypeName":"Базовый","slug":"magicalLineage","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Благодаря врожденному таланту, прихоти богов или маниакальному изучению необычных книг, вы освоили использование одного фокуса. Выберите заклинание 0-ого круга. Вы можете колдовать это заклинание раз в день как псевдозаклинание. Уровень заклинателя этого псевдозаклинания будет равен вашему наивысшему уровню заклинателя. Если у вас нет уровня заклинателя, считайте его равным 1-му для этого заклинания. Проверка сложности испытания этого псевдозаклинания зависит от <a href=\"/ability/charisma\" class=\"link\">Харизмы</a>.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Magical Talent","nameRu":"Магический талант","parentTypeName":"Базовый","slug":"magicalTalent","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Ваши многолетние изучения искусства призыва даровали вам исключительные знания этой тонкой и сложной дисциплины. Раз в день, читая заклинание <a href=\"/spell/schools\" class=\"link\">школы воплощения</a>, для определения длительности заклинания вы можете считать ваш уровень заклинателя выше на 2.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Master of Pentacles","nameRu":"Мастер пентаклей","parentTypeName":"Штрих фракции","slug":"masterOfPentacles","typeAlias":"darkArchive","typeName":"Темный архив"},{"benefit":"Математика вам всегда легко давалась, вам проще «увидеть математику» в магических или физических явлениях, чем многим другим. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (магия) и <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (инженерное дело), и один из этих навыков (на ваш выбор) - всегда классовый для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Mathematical Prodigy","nameRu":"Математический гений","parentTypeName":"Базовый","slug":"mathematicalProdigy","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Ваша дотошная осторожность делает ваши бомбы и экстракты более мощными. Раз в день вы можете добавить +2 (штрих) к СЛ испытания для одной метаемой бомбы или увеличить длительность одного выпиваемого вами экстракта на 2 раунда. Этот штрих не влияет на экстракты с мгновенной длительностью.","book":"Ultimate Campaign","kind":"trait","nameEn":"Meticulous Concoction","nameRu":"Дотошный смешиватель","parentTypeName":"Базовый","slug":"meticulousConcoction","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"Вы подозреваете, что ребёнок, которого вы знали, был похищен Гаэдреном Ламмом. Независимо от отношения, вы слышали слухи о \"Ягнятах Ламма\" и как старик использует детей в качестве карманников и исполнителей для его преступлений. До вас даже дошли слухи, что разыскиваемый вами ребёнок был замечен на рынке в компании известных карманников и воров. Хотя Стража Корвосы понимает вашу беду, всё же кажется, что они заняты \"более важными\" делами в эти дни, и не имеют возможности узнать больше о Гаэдрене. Никто больше не заинтересован в поимке Гаэдрена и освобождении его жертв - эта задача ложится на вас. И всё же, где же прячется этот старый мерзавец?\nВыберите одно из следующих преимуществ.\n<b>Пропавший брат/сестра:</b> пропавший ребёнок - это брат или сестра. Хотя все остальные уже потеряли надежду, вы верите, что ваш родич всё ещё жив. Постоянные поиски потерянного родича развили ваши способности собирать слухи и получать информацию от других. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/senseMotive\" class=\"link\">Проницательности</a> и <a href=\"/skill/senseMotive\" class=\"link\">Проницательность</a> становится классовым навыков для вас.\n<b>Пропавший сын или дочь:</b> пропавший ребёнок - это ваш собственный сын или дочь, племянник или племянница, или ребёнок, которого обязались защищать. Этот ребёнок был похищен по дороге на рынок или во время другого повседневного дела. Ваше упрямство и долгие часы, потраченные на сбор слухов дают вам бонус (штрих) +1 к испытаниям Воли.","book":"Curse of the Crimson Throne","kind":"trait","nameEn":"Missing Child","nameRu":"Потерянное дитя","parentTypeName":"Штрих кампании","slug":"missingChild","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"Вы росли в Магнимаре и с детства восторгались древними памятниками, которыми так богат этот город. За прошедшие годы ваше увлечение только возросло, что и побудило вас вступить в Общество Искателей, чтобы полнее утолить жажду знаний. Хотя вы мало что знаете о подлинной истории монументов, вы всесторонне изучили эти колоссальные творения. Благодаря близкому знакомству с памятниками истории вы получаете бонус +1 (штрих) к проверкам <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (история), сделанным в Варисии. Если проверка касается города Магнимар, этот бонус увеличивается до +2. Кроме того, вы получаете бонус +2 (штрих) к любой проверке навыка, сделанной для получения дара одного из магических памятников Магнимара.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Monument Scholar","nameRu":"Знаток памятников","parentTypeName":"Штрих кампании","slug":"monumentScholar","typeAlias":"shatteredStar","typeDescription":"Следующие штрихи кампании помогут создать персонажа, подходящего для серии приключений «Расколотая звезда». Лучше всего, если он живёт в городе Магнимар или недавно сюда прибыл. Также желательно либо состоять в Обществе Искателей, либо быть готовым вступить в его местную ложу.","typeName":"Расколотая звезда"},{"benefit":"Всегда так выходило, что на вас смотрели как на лидера, вы даже можете припомнить случай из детства как вы возглавили группу других детей и достигли определенной цели, что невозможно было сделать по отдельности. Все соратники, последователи и вызванные существа под вашим лидерством получают +1 бонус (штрих) к испытаниям Воли для избегания воздействия на разум. Если вы возьмете черту <a href=\"/feat/leadership\" class=\"link\">Лидерство</a>, вы получите +1 бонус (штрих) к своему значению <a href=\"/feat/leadership\" class=\"link\">Лидерства</a>.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Natural-Born Leader","nameRu":"Прирожденный лидер","parentTypeName":"Базовый","slug":"naturalBornLeader","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Переговоры с существами, будь то человек или животное из далекого мира - ваша вторая натура. Либо <a href=\"/skill/diplomacy\" class=\"link\">Дипломатия</a>, либо <a href=\"/skill/handleAnimal\" class=\"link\">Дрессировка</a> становится для вас классовым навыком. Добавьте к известным вам языкам один на выбор: акло, акван, ауран, игнан, сильван или терран.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Natural Negotiator","nameRu":"Естественный переговорщик","parentTypeName":"Штрих фракции","slug":"naturalNegotiator","typeAlias":"concordance","typeName":"Гармония"},{"benefit":"Вы из шоанти или коренных варисийцев. Вы покинули родных и друзей, чтобы разобраться в тайнах своей удивительной родины. Недавно судьба привела вас в магнимарскую ложу Искателей. Хотя никого из семьи нет рядом, они всегда с вами - в ваших семейных традициях.\nЕсли вы варисиец, то получаете бонус +1 (штрих) к проверкам <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (география), касающимся Варисии, и бонус +1 (штрих) к броскам урона в предбоевом раунде, когда вы используете <a href=\"/weapons?menu=alphabet_П&scroll=shawlWithBlades\" class=\"link\">платок с лезвиями</a> или <a href=\"/weapons?menu=alphabet_Н&scroll=starknife\" class=\"link\">нож-звезду</a>.\nЕсли вы шоанти, то получаете бонус +1 (штрих) к проверкам <a href=\"/skill/survival\" class=\"link\">Выживания</a> в Варисии и бонус +1 (штрих) к броскам на подтверждение критического удара, нанесённого <a href=\"/weapons?menu=alphabet_К&scroll=earthBreaker\" class=\"link\">камнеломом</a> или <a href=\"/weapons?menu=alphabet_К&scroll=klar\" class=\"link\">кларом</a>.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Nontraditional Native","nameRu":"Необычный местный","parentTypeName":"Штрих кампании","slug":"nontraditionalNative","typeAlias":"shatteredStar","typeDescription":"Следующие штрихи кампании помогут создать персонажа, подходящего для серии приключений «Расколотая звезда». Лучше всего, если он живёт в городе Магнимар или недавно сюда прибыл. Также желательно либо состоять в Обществе Искателей, либо быть готовым вступить в его местную ложу.","typeName":"Расколотая звезда"},{"benefit":"Вы всегда уделяете внимание окружению и людям, которых встречаете. Выберите <a href=\"/skill/perception\" class=\"link\">Внимание</a> или <a href=\"/skill/senseMotive\" class=\"link\">Проницательность</a>; вы получаете бонус (штрих) +1 на проверки выбранного навыка, и он становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Observant","nameRu":"Наблюдатель","parentTypeName":"Штрих фракции","slug":"observant","typeAlias":"grandLodge","typeName":"Великая ложа"},{"benefit":"Ваш опыт межпланарных путешествий дает вам преимущество в сражениях за пределами материального плана. Вы получаете бонус (штрих) +1 к проверкам инициативы и испытаниям, когда вы не находитесь на материальном плане.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Planar Voyager","nameRu":"Межпланарный путешественник","parentTypeName":"Штрих фракции","slug":"planarVoyager","typeAlias":"concordance","typeName":"Гармония"},{"benefit":"Ваше детство было тяжелым и ваши родители тряслись над каждым медяком. Вы постоянно голодали и вам часто приходилось спать на голой земле или даже в лесу. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/survival\" class=\"link\">Выживания</a>, а <a href=\"/skill/survival\" class=\"link\">Выживание</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Poverty-Stricken","nameRu":"Выросший в бедности","parentTypeName":"Базовый","slug":"povertyStricken","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Ваше обучение в Великой ложе не прошло даром. Выберите <a href=\"/skill/knowledge\" class=\"link\">Знание</a> (география) или <a href=\"/skill/knowledge\" class=\"link\">Знание</a> (история); вы получаете бонус (штрих) +1 на проверки выбранного навыка и он становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Proper Training","nameRu":"Правильное обучение","parentTypeName":"Штрих фракции","slug":"properTraining","typeAlias":"grandLodge","typeName":"Великая ложа"},{"benefit":"Над вами часто издевались в детстве, но вы никогда не зацикливались на агрессии в ответ на издевательства. Вместо этого вы стали мастером упреждающих внезапных атак и быстрого реагирования на опасности. Вы получаете +2 бонус (штрих) к проверкам Инициативы.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Reactionary","nameRu":"Готовый к опасности","parentTypeName":"Базовый","slug":"reactionary","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Подрастая в жестоком окружении или в непрощающих ошибок дебрях, вы часто были вынуждены пить и есть из сомнительных источников. В результате вы закалили свой характер и получаете +1 бонус (штрих) к испытаниям Стойкости.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Resilient","nameRu":"Привыкший к невзгодам","parentTypeName":"Базовый","slug":"resilient","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Некоторые из самых мощных оружий бесценные и древние, и вы защищаете свое снаряжение так же, как себя. Вы получаете бонус (штрих) +1 к вашей защите от боевых маневров против разоружения, кражи и разрушения, и ваше снаряжение получает бонус (штрих) +1 на все испытания.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Reverent Wielder","nameRu":"Почтительный владелец","parentTypeName":"Штрих фракции","slug":"reverentWielder","typeAlias":"scarabSages","typeName":"Мудрецы скарабея"},{"benefit":"Вы родились в богатой семье, возможно, даже знатной, но все равно вы стали искателем приключений. Вам было очень приятно получить единичную выплату к своей стартовой сумме и теперь она увеличилась до 900 зм.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Rich Parents","nameRu":"Богатые родители","parentTypeName":"Базовый","slug":"richParents","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы способны выразить свои убеждения так, что другие проникнутся ими. <a href=\"/skill/perform\" class=\"link\">Исполнение</a> (действие, комедия, ораторство или пение) становится для вас классовым. Раз в день вы можете обратиться к своим союзникам в радиусе 60 футов и в течение 1 минуты воодушевить их. Сделайте проверку <a href=\"/skill/perform\" class=\"link\">Исполнения</a> (действие, комедия, ораторство или пение) со сложностью 15. Если она была успешной, то союзники получают бонус (штрих) +1 на испытания против эффектов страха на 5 минут. Если вы превысили сложность на 10 или более, бонус увеличивается до +2.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Rousing Oratory","nameRu":"Воодушевляющая речь","parentTypeName":"Штрих фракции","slug":"rousingOratory","typeAlias":"libertyEdge","typeName":"Клинок свободы"},{"benefit":"Хотя вас, привыкшего везде видеть выгоду, и привлекает торговля, вы выбираете более рискованный путь к богатству - поиск редких реликвий и продажу их тому, кто больше заплатит. Вы решили присоединиться к Искателям, чтобы иметь возможность путешествовать по всей Варисии в поисках сокровищ, а взамен предложили Обществу свой острый глаз и умение отличать подлинные реликвии от подделок. Вы получаете бонус +1 (штрих) к проверкам <a href=\"/skill/appraise\" class=\"link\">Оценки</a>. Кроме того, у вас есть бонус +4 к проверкам <a href=\"/skill/perception\" class=\"link\">Внимания</a>, сделанным для того, чтобы отличить подобных статуям существ (например, кариатид и <a href=\"/bestiary/beast/gargoyle\" class=\"link\">гаргулий</a>) от настоящих скульптур.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Ruin Raider","nameRu":"Расхититель руин","parentTypeName":"Штрих кампании","slug":"ruinRaider","typeAlias":"shatteredStar","typeDescription":"Следующие штрихи кампании помогут создать персонажа, подходящего для серии приключений «Расколотая звезда». Лучше всего, если он живёт в городе Магнимар или недавно сюда прибыл. Также желательно либо состоять в Обществе Искателей, либо быть готовым вступить в его местную ложу.","typeName":"Расколотая звезда"},{"benefit":"Ваше рождение было мучительным и трудным для вашей матери и она нуждалась в определенной сакральной магии чтобы пережить роды. Ваша мать могла как выжить, так и погибнуть при родах. В любом случае, с раннего возраста вы были пропитаны магией и сейчас вы проводите сакральную энергию лучше многих. Когда вы проводите энергию, вы получаете +1 бонус (штрих) к сложности испытания против вашей проведенной энергии.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Sacred Conduit","nameRu":"Священный проводник","parentTypeName":"Базовый","slug":"sacredConduit","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"В детстве вы были подвержены излучению мощного источника позитивной энергии: возможно вы были рождены под особым космическим знаком или один из ваших родителей был одаренным целителем. Стандартным действием вы можете автоматически стабилизировать умирающее существо просто дотронувшись до него.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Sacred Touch","nameRu":"Священное прикосновение","parentTypeName":"Базовый","slug":"sacredTouch","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Вы изучали баланс стихий и его воздействие на природные и планарные силы. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (природа) и <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (планы), и один из этих навыков (на ваш выбор) становится классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Scholar of Balance","nameRu":"Ученик баланса","parentTypeName":"Штрих фракции","slug":"scholarOfBalance","typeAlias":"concordance","typeName":"Гармония"},{"benefit":"Большинство ваших детских интересов лежало за пределами обыденности, вы не могли найти свое место в жизни, словно были рождены не в ту эру. Вам легко даются философские дискуссии о Великом Запределье и исторических событиях. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (история) и <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (планы), и один из этих навыков (на ваш выбор) - всегда классовый для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Scholar of the Great Beyond","nameRu":"Исследователь Великого Запределья","parentTypeName":"Базовый","slug":"scholarOfTheGreatBeyond","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"Ваши предки верно чтили Нефиса, и он наградил их потомков даром прорицания. Раз в день вы получаете бонус (штрих) +2 на любую проверку <a href=\"/skill/knowledge\" class=\"link\">Знания</a>. Вдобавок, выберите один навык <a href=\"/skill/knowledge\" class=\"link\">Знаний</a>, он теперь классовый для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Secrets of the Sphinx","nameRu":"Секреты сфинкса","parentTypeName":"Штрих фракции","slug":"secretsOfTheSphinx","typeAlias":"scarabSages","typeName":"Мудрецы скарабея"},{"benefit":"Вы участвовали в потешных гладиаторских боях и спортивных состязаниях на грандиозном Змеином ипподроме. Но вам не хватало настоящей опасности. В погоне за острыми ощущениями и желая испытать себя в чём-то новом, вы предложили свои услуги местной ложе Искателей. Выберите одно из следующих преимуществ, чтобы воплотить технику, которой вы научились на Змеином ипподроме:\n<ul>\n    <li>Выберите определённый тип брони. Когда вы носите доспех этого типа, штраф за доспехи для вас на 1 меньше.</li>\n    <li>Когда вы сражаетесь парным оружием, штраф, наложенный на ваше основное оружие, уменьшается на 1.</li>\n    <li>Вы получаете бонус +2 (штрих) к проверкам <a href=\"/skill/intimidate\" class=\"link\">Запугивания</a> для деморализации противников.</li>\n</ul>","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Serpent Runner","nameRu":"Змеиный бегун","parentTypeName":"Штрих кампании","slug":"serpentRunner","typeAlias":"shatteredStar","typeDescription":"Следующие штрихи кампании помогут создать персонажа, подходящего для серии приключений «Расколотая звезда». Лучше всего, если он живёт в городе Магнимар или недавно сюда прибыл. Также желательно либо состоять в Обществе Искателей, либо быть готовым вступить в его местную ложу.","typeName":"Расколотая звезда"},{"benefit":"В детстве вы часто видели магические эффекты и поняли, что большинство из них - пускание пыли в глаза. Вы получаете +2 бонус (штрих) к испытаниям против иллюзий.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Skeptic","nameRu":"Скептик","parentTypeName":"Базовый","slug":"skeptic","typeAlias":"magic","typeDescription":"Эти штрихи связаны с магией и сосредоточены на колдовстве и манипуляциях магией. Вам не обязательно быть заклинателем чтобы взять Магический штрих (однако некоторые из этих штрихов бесполезны для незаклинателей). Магические штрихи могут представлять раннее проявление магии в персонаже или его обучение магии в детстве.","typeName":"Магический"},{"benefit":"У вас набита рука скрывать товары от бдительного взора, будь то контрабанда или просто подотчетная вещь. Вы получаете бонус (штрих) +3 на проверки <a href=\"/skill/sleightOfHand\" class=\"link\">Ловкости Рук</a>, чтобы спрятать объекты, и этот навык становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Smuggler","nameRu":"Контрабандист","parentTypeName":"Штрих фракции","slug":"smuggler","typeAlias":"theExchange","typeName":"Торговый союз"},{"benefit":"Вас гложет темный голод, проявляющийся, когда вы или союзник убиваете противника. Раз в день при смерти вражеского существа, как прерывающее действие, вы можете получить на 1 минуту временные очки здоровья, количество которых равно кубику здоровья убитого врага. Это сверхъестественная способность.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Soul Drinker","nameRu":"Пожиратель душ","parentTypeName":"Штрих фракции","slug":"soulDrinker","typeAlias":"darkArchive","typeName":"Темный архив"},{"benefit":"Вам доступна сила древних паладинских орденов Голариона благодаря записям Общества об их героических деяниях. Из-за этого ваша классовая способность аура доблести даёт дополнительный бонус +1 (штрих) к испытаниям против эффектов ужаса.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Stalwart of the Society","nameRu":"Оплот Общества","parentTypeName":"Базовый","slug":"stalwartOfTheSociety","typeAlias":"faith","typeDescription":"Эти штрихи основаны на твердости духа, восприятии и религии, но напрямую не связаны со служением определенному божеству. Вовсе не обязательно поклоняться определенному божеству, чтобы взять эти штрихи, так как они могут представлять уверенность в себе или в какой-либо философии так же, как и приверженность определенному божеству.","typeName":"Штрих веры"},{"benefit":"В раннем возрасте вы обнаружили, что человек, которому вы безоговорочно доверяли, например, старший брат или родителя, лгал вам, причем вы это воспринимали как должное, что в свою очередь заставило вас сомневаться в искренности всех остальных. Вы получаете +1 бонус (штрих) к проверкам <a href=\"/skill/senseMotive\" class=\"link\">Проницательности</a>, а <a href=\"/skill/senseMotive\" class=\"link\">Проницательность</a> - всегда классовый навык для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Suspicious","nameRu":"Недоверчивый","parentTypeName":"Базовый","slug":"suspicious","typeAlias":"social","typeDescription":"Социальные штрихи - это некая всеобъемлющая категория, эти штрихи отражают социальное воспитание вашего персонажа, ваше связанное с дворянством прошлое или его отсутствие, а также историю ваших родителей, родственников, друзей, соперников и врагов.","typeName":"Социальный"},{"benefit":"Вы знаете, как воспользоваться ситуацией, когда враг не готов к вашему нападению. Вы получаете +1 (штрих) на проверки инициативы. Кроме того, раз в день, когда проводите внеочередную атаку, вы получаете +2 (штрих) на проверку атаки.","book":"Ultimate Campaign","kind":"trait","nameEn":"Tactician","nameRu":"Тактик","parentTypeName":"Базовый","slug":"tactician","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вы знаете последствия провала и стараетесь не наступать на те же грабли дважды. Раз в сценарий, когда вы выкинете естественную единицу на любое испытание, вы получаете бонус (штрих) +1 на ваше следующее испытание, который должен быть использован до конца сценария.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Teaching Mistake","nameRu":"Наступил на грабли","parentTypeName":"Штрих фракции","slug":"teachingMistake","typeAlias":"grandLodge","typeName":"Великая ложа"},{"benefit":"Вы привыкли трудиться долгие часы в сложных условиях, чтобы выполнить работу любой ценой. Вы получаете бонус (штрих) +2 ко всем проверкам <a href=\"/ability/constitution\" class=\"link\">Выносливости</a> против нелетального урона от плавания, марш-бросков, голода, жажды и жаркого и холодного окружения. Вдобавок, вы получаете 1 пункт здоровья.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Tireless","nameRu":"Неутомимый","parentTypeName":"Штрих фракции","slug":"tireless","typeAlias":"theExchange","typeName":"Торговый союз"},{"benefit":"Большую часть жизни вы провели, исследуя древние гробницы и катакомбы Мудрецов скарабея. Вы получаете бонус черты +1 на проверки <a href=\"/skill/perception\" class=\"link\">Внимания</a> и <a href=\"/skill/knowledge\" class=\"link\">Знания</a> (подземелья). Один из этих навыков (на ваш выбор) становится классовым для вас.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Tomb Raider","nameRu":"Расхититель гробниц","parentTypeName":"Штрих фракции","slug":"tombRaider","typeAlias":"scarabSages","typeName":"Мудрецы скарабея"},{"benefit":"За годы, проведённые среди Искателей, вы в совершенстве освоили искусство выслеживания. Вы получаете бонус +1 (штрих) к проверкам инициативы и бонус +2 (штрих) к проверкам <a href=\"/skill/survival\" class=\"link\">Выживания</a> при передвижении по любой из ваших излюбленных местностей. Они суммируются со всеми бонусами, которые вы получаете от своей классовой способности излюбленная местность.","book":"Shattered Star - Player's Guide","kind":"trait","nameEn":"Tracker of the Society","nameRu":"Ищейка Общества","parentTypeName":"Базовый","slug":"trackerOfTheSociety","typeAlias":"combat","typeDescription":"Эти штрихи связаны со схватками боями и физическим мастерством они дают персонажу маленькие бонусы в бою и представляют конфликты и физические усилия в предыстории персонажа.","typeName":"Боевой"},{"benefit":"Вы выросли в опасной зоне и были постоянно окружены ловушками, созданными, чтобы защитить ваш дом от злоумышленников. Иногда эти опасности были настолько плотно расставлены, что вы не могли пройти и пару футов вниз по туннелю, не столкнувшись с новым способом умереть. Вы получаете +1 (штрих) на проверки <a href=\"/skill/craft\" class=\"link\">Ремесла</a> (капканщик) и +1 (штрих) к КБ против атак ловушек или на испытания от эффектов, созданных ловушками.","book":"Kobolds of Golarion","kind":"trait","nameEn":"Trap Savvy","nameRu":"Подкованный в ловушках","prerequisites":"Темноземье","slug":"trapSavvy","typeAlias":"regional","typeDescription":"Региональные штрихи связаны с определенными регионами, которые могут быть крупными (такие как нация или географический регион) или небольшими (такие как город или определенная гора). Если вы хотите взять себе региональный штрих, вашему персонажу необходимо прожить в соответствующем месте как минимум год. На первом уровне вы можете выбрать только один региональный штрих (обычно он связан с местом рождения персонажа или родиной), независимо от количества регионов, описанных в предыстории вашего персонажа.","typeName":"Региональный"},{"benefit":"То ли вы настолько преданы делу, то ли у вас кишка не тонка, но ничто не может вас потрясти. Вы получаете бонус (штрих) +1 к испытаниям против страха, и сложность <a href=\"/skill/intimidate\" class=\"link\">Запугивания</a>, чтобы деморализовать вас, повышается на 1.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Unflappable","nameRu":"Невозмутимый","parentTypeName":"Штрих фракции","slug":"unflappable","typeAlias":"sovereignCourt","typeName":"Суверенный двор"},{"benefit":"Вы провели определённое время как один из порабощённых сирот Гаэдрена Ламма, выполняя всю грязную работу за него. Возможно, вас похитили из родительского дома или по пути на рынок. Возможно, безответственная матрона, которая руководила приютом, продала вас ему, отчаянно нуждаясь в деньгах. Или, может быть, вы, как и большинство рабов Гаэдрена, были обычным уличным пострелом, который поддался его обещанию регулярной еды и крыши над головой в обмен на то, что он сказал, будет «небольшой лёгкой работой». В любом случае, вы провели несколько лет своей жизни, как один из «Ягнят Ламма», прежде чем сбежать. С тех пор вы лелеяли злобу по отношению к старику.\n<b>Измученный:</b> после того, как вы сделали слишком много ошибок, Гаэдрен пытал вас и оставил умирать в куче мусора. Ваши шрамы и воспоминания мотивировали оттачивать скорость реакции и стать прыгучее. Вы получаете бонус (штрих) +1 к испытаниям Реакции.\n<b>Религиозный:</b> однажды во время работы на Гаэдрена, вы нашли символ религии бога, которому поклоняетесь, и, заинтригованный им, тайком убегали, чтобы посещать службы. Когда Гаэдрен узнал, он избил Вас почти до смерти и сломал символ религии. Вера позволила вам отгородиться от боли, и вы сбежали из под его контроля и укрылись в церкви, где провели остаток своей юности. Вы получаете бонус (штрих) +2 к проверкам Концентрации и проверкам <a href=\"/ability/constitution\" class=\"link\">Выносливости</a> для стабилизации при отрицательных ПЗ.","book":"Curse of the Crimson Throne","kind":"trait","nameEn":"Unhappy Childhood","nameRu":"Несчастливое детство","parentTypeName":"Штрих кампании","slug":"unhappyChildhood","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"Вы особенно быстры на своих ногах и получаете бонус +2 к проверкам <a href=\"/skill/acrobatics\" class=\"link\">Акробатики</a>, чтобы перемещаться через клетки, находящиеся под угрозой врага.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Unorthodox Strategy","nameRu":"Неортодоксальная стратегия","parentTypeName":"Штрих фракции","slug":"unorthodoxStrategy","typeAlias":"silverCrusade","typeName":"Серебряный поход"},{"benefit":"Вы предпочитаете завоевывать доверие и хорошее отношение клиентов честными сделками. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/diplomacy\" class=\"link\">Дипломатии</a> и <a href=\"/skill/senseMotive\" class=\"link\">Проницательности</a>, и один из этих навыков (на ваш выбор) становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Upstanding","nameRu":"Честный","parentTypeName":"Штрих фракции","slug":"upstanding","typeAlias":"theExchange","typeName":"Торговый союз"},{"benefit":"Ваша семья особенно чтит семейные традиции и даже сохранила предания о варисийком предке, который стремился вылечить (или, как говорят некоторые болтливые родственники, создавать) болезни. Вы получаете бонус (штрих) +1 к испытаниям Стойкости против болезней. Кроме того, вы невосприимчивы к болезни Вореля и болезни под названием вуаль крови. Вам не нужно быть варисийцем по этнической принадлежности, чтобы взять этот штрих кампании, но ваша предыстория должна объяснять, откуда у вас взялся варисийкий предок.","book":"Varisia, Birthplace of Legends","kind":"trait","nameEn":"Varisian Immunity","nameRu":"Варисийкий иммунитет","parentTypeName":"Штрих кампании","slug":"varisianImmunity","typeAlias":"curseOfTheCrimsonThrone","typeDescription":"Еще до того, как начнется «Проклятие Багрового Трона», у вас и других персонажей есть общая особенность - вы все так или иначе пострадали от презренного Гаэдрена Ламма. Кампания начинается с того, что вы и несколько других многообещающих молодых героев собрались вместе, чтобы сделать то, что городская стража не может (или не хочет) сделать - чтобы Гэдрен Ламм ответил за свои преступления, будь то в суде или на острие мстительного клинка. Здесь представлены несколько связей с Гаэдреном, которые вы можете выбрать для своего персонажа, исторические фрагменты, которые объясняют, как этот отвратительный криминальный авторитет влиял на вас в прошлом. Каждый штрих представляет собой неудачное событие, описанное в общих чертах, чтобы вы могли настроить его в соответствии со своими потребностями, которые помогли бы сформировать вашего персонажа. После того, как вы выбрали штрих, выберите преимущество, которое соответствует вашей собственной концепции для вашего персонажа. Не стесняйтесь адаптировать и перерабатывать детали выбранного вами штриха, чтобы они соответствовали вашей истории. Пока у вас есть причина увидеть, как Гаэдрен расплачивается за свои преступления, у вас будет причина начать жизнь приключений и, что более важно, причина сблизиться со своими новыми товарищами. Очевидно, что эти штрихи не будут хорошо работать для новых персонажей, добавленных в кампанию после того, как о Гаэдрене позаботились, но текст описания можно легко изменить. Поговорите со своим ведущим, но вам не составит труда выбрать один из следующих штрихов, изменить несколько имен и сфокусировать ее на совершенно другом наборе обстоятельств. Ваш ведущий должен решить, решал ли уже ваш новый высокоуровневый персонаж эти проблемы или он хочет включить их в будущие события кампании. Игровые преимущества выбранного штриха остаются неизменными и сохраняются даже после того, как о Гаэдрен Ламм позаботятся.","typeName":"Проклятие Багрового трона"},{"benefit":"Вы в курсе схем лжецов, воров и мошенников. Вы получаете бонус (штрих) +1 на проверки <a href=\"/skill/senseMotive\" class=\"link\">Проницательности</a>. Этот навык становится для вас классовым.","book":"Character Traits Web Enhancement","kind":"trait","nameEn":"Whistleblower","nameRu":"Осведомитель","parentTypeName":"Штрих фракции","slug":"whistleblower","typeAlias":"libertyEdge","typeName":"Клинок свободы"}]};
